/**
 * Replay harness. Analysis §4.4 step 9 and §6.6:
 *
 *   "Every week, run the same code on last year's bergs and publish geodesic
 *    MAE. If skill dies, we know before a voyage."
 *
 * This is also where the conformal cone gets its calibration scores. The cone
 * is honest only if it is calibrated against real out-of-sample error, so the
 * same routine feeds both the skill table and `buildCone`.
 *
 * Ground truth is generated by a *separate* forcing realisation (different
 * perturbation seed, plus unresolved sub-grid motion) so the model is scored
 * against something it has not seen — not against its own output.
 */

import { integrateTrajectory, mulberry32, type DriftRequest } from "@/lib/physics/drift";
import { DEFAULT_RESIDUAL_MODEL } from "@/lib/physics/residual";
import { mesoscaleBiasField, climatologicalBias } from "@/lib/fields/forcing";

const M_PER_DEG = 111320;
import { geodesicKm } from "@/lib/geo/geodesic";
import type { SizeClass } from "@/lib/physics/force-balance";

export interface ReplayCase {
  id: string;
  bergId: string;
  displayName: string;
  sizeClass: SizeClass;
  start: { lat: number; lon: number; u: number; v: number };
  startAt: Date;
  /** Which voyage-season the case belongs to; used for the seasonal split (L12). */
  season: "SUMMER" | "AUTUMN" | "WINTER" | "SPRING";
}

